/* Session 1: one teaching sequence per topic. Source reconciliation lives in the audit ledger. */
function integrateSession1(){
 const p=(...items)=>items.map(x=>`<p>${x}</p>`).join('');
 const set=(id,body)=>{lessons.find(l=>l.id===id).body=body;};

 set('roots',
 section('根系、接穗与砧木',
 p('根系负责<strong>吸收、固定、储存</strong>：吸收土壤水分与矿物养分，固定葡萄藤，储存越冬及来春生长所需的碳水化合物；不从土壤吸收糖或“石头味”。',
 '<strong>接穗 Scion</strong> 是希望种植的酿酒品种枝段，长出地上部分并结果；<strong>砧木 Rootstock</strong> 提供下部结构和根系。把霞多丽接到抗性砧木上，结果的品种仍是霞多丽。')+
 table(['葡萄种 Species','用途与识别'],[
 ['Vitis vinifera · 欧亚葡萄','起源于欧亚交界、中东一带，包含霞多丽、赤霞珠等绝大多数常见酿酒品种，通常提供接穗。'],
 ['Vitis berlandieri · 冬葡萄','用于砧木育种的美洲葡萄种之一。'],
 ['Vitis riparia · 河岸葡萄','用于砧木育种的美洲葡萄种之一。'],
 ['Vitis rupestris · 沙地葡萄','用于砧木育种的美洲葡萄种之一。']
 ])+p('北美原生葡萄的果实风味通常不符合主流欧亚品种酒的风格，根系抗性却适合砧木育种。美洲葡萄或种间杂交葡萄并非都不能酿酒，如加拿大的 Vidal 可用于冰酒。'))+
 section('根瘤蚜与抗性砧木',
 p('<strong>根瘤蚜 Phylloxera</strong> 原产北美，19 世纪 60 年代意外传入欧洲后造成大面积葡萄园损失和经济危机。其生命周期复杂，部分阶段在地下取食根系；伤口可继发病原体感染，使葡萄藤在数年内衰弱甚至死亡。',
 '与害虫长期共同演化的美洲葡萄能分泌黏液干扰取食，并在伤口形成保护层，减少继发感染。欧亚葡萄通常缺乏相同防御，单靠化学药剂不能可靠地解决根瘤蚜问题。')+
 flow('根系受害并继发感染','吸水与生长受影响，植株衰弱','以抗性根系保护所需酿酒品种')+
 p('并非所有葡萄藤都必须嫁接。智利、阿根廷部分地区、南澳大利亚等地有未受侵袭的背景和严格检疫要求，但仍存在风险。即使没有根瘤蚜，也可能为防御线虫或改善耐旱性选择砧木。',
 '砧木还须适应当地水分、盐碱等土壤条件及所需长势；没有兼具所有优点的砧木，嫁接苗也增加购置成本。'))+
 section('室内嫁接与田间换接',
 table(['方式','操作过程','时间与成本取舍'],[
 ['室内嫁接 Bench grafting','苗圃在可控环境中连接短段接穗和砧木，可用机器完成接合；在温暖条件下使接口愈合，保护接口、培育成苗，再栽入葡萄园。接穗上须保留芽；接口可见红蜡等保护材料。','常用于建立新园。新栽葡萄藤通常至少到第三年才有商业收成。'],
 ['田间换接／头接枝法 Head grafting','将已建立的葡萄藤剪到保留主干和既有根系，把所需新品种的芽或枝段接上；绑带固定，蜡或修剪漆等材料保护连接处。','用于更换不合适的品种，成功后可在下一年结出新品种的果实。田间操作较麻烦、需要人工；相对拔除整园并重新栽种，通常更快、成本更低。']
 ])+p('保护材料可不同，目的都是固定、保护和促进接口愈合。田间换接虽需人工，相比整园重植仍通常更省钱。')+
 courseFigure('botany','观察苗圃嫁接与田间换接：辨认接穗上的芽、接合位置、保护材料，以及换接后保留的主干和根系。'))+
 section('嫁接改变生长条件，不创造杂交品种',
 p('嫁接连接两部分，不通过授粉、受精重组亲本基因，因此不创造杂交新品种。<a href="#lesson/propagation">扦插、压条与杂交 →</a>',
 '砧木通过长势、抗性及根系的环境适应影响植株健康与成熟，并非把“美洲根系的味道”传进葡萄。')+
 callout('抗性砧木的作用','减少根瘤蚜伤根 → 维持吸水与生长；地上部分仍保留所需酿酒品种。',true))
 );

 set('propagation',
 section('属、种、品种与品系',
 table(['层级','英文','例子与含义'],[
 ['属','Genus','Vitis · 葡萄属。'],
 ['种','Species','Vitis vinifera · 欧亚葡萄。欧亚交界、中东及土耳其一带可作为理解其起源范围的地理线索。'],
 ['品种','Variety / Cultivar','Chardonnay · 霞多丽、Pinot Noir · 黑皮诺；不能把 variety 与 species 当成同一级。'],
 ['品系／克隆','Clone','一个品种中从特定母株连续无性繁殖的后代；Gingin 是霞多丽的品系例子。']
 ])+p('消费者关注颜色、风味与品质；种植者还要考虑萌芽、成熟、抗病性及气候和土壤适应性。同一品种的克隆可在果粒大小、产量、成熟和品质上有差别，通常仍属原品种。'))+
 section('扦插与压条：保留母株的品种性状',
 table(['无性繁殖方式','怎样进行','保留什么、须注意什么'],[
 ['扦插 Cutting','取一段枝条培育，使其长出根系，形成新植株；商业苗圃常用，现代建园通常配合抗性砧木嫁接。','延续母株的品种性状。'],
 ['压条 Layering','把仍连接母株的长枝弯下，将中段埋土、枝梢留在地面之上；埋入部分生根，数年后切断与母株的连接。','延续母株性状，但根系来自原植株，不能因此获得嫁接抗性砧木所提供的根瘤蚜保护。']
 ])+p('克隆群可由同一母株连续扦插和／或压条而成。种子繁殖重组基因，不能稳定保留原品种性状。')+
 courseFigure('botany','压条的埋土枝段在生根前仍连接母株；这与把接穗接到另一株抗性根系上的嫁接不同。'))+
 section('突变与克隆选择：保留差异，不等于杂交',
 p('无性繁殖保留品种身份，仍可能发生突变。选择品质、抗病性等更好的植株，再无性繁殖以保留性状，称为<strong>克隆选择 Clonal selection</strong>。订苗可同时指定品种与克隆。',
 '克隆差别通常较小；少数显著突变习惯上被视作不同品种。Pinot Blanc、Pinot Gris、Pinot Noir 与 Meunier 均与古老 Pinot 的变异有关；这种变异不同于亲本授粉产生的后代。'))+
 section('有性繁殖：新组合怎样形成',
 p('人工异花授粉将一亲本花粉授给另一亲本，受精形成种子。播种后幼苗的基因组合不同于亲本；即使亲本同属一个品种，也不能保证复制原品种。育种目标包括气候和土壤适应性、抗病性、果实质量及产量。')+
 flow('亲本授粉、受精','形成种子并播种','观察、筛选新的遗传组合')+
 table(['亲本关系','术语','例子与用途'],[
 ['同一种内的亲本','种内杂交 Crossing','不只欧亚葡萄才会发生种内杂交；天然与人工选择都可能形成有价值的品种。'],
 ['不同葡萄种的亲本','种间杂交 Hybrid','典型组合中至少有一个美洲葡萄亲本。许多用于砧木，也有以果实酿酒的例外，如加拿大的 Vidal · 威代尔可用于冰酒。美洲种的种内杂交与种间杂交都能参与砧木培育。']
 ])+table(['品种例子','亲本或特点'],[
 ['Cabernet Sauvignon · 赤霞珠','天然种内杂交：Cabernet Franc · 品丽珠 × Sauvignon Blanc · 长相思；现代遗传分析确认其亲本关系。'],
 ['Müller-Thurgau · 米勒图高','人工种内杂交：Riesling · 雷司令 × Madeleine Royale。不要仅凭名称推断亲本。'],
 ['Pinotage · 皮诺塔吉','人工种内杂交：Pinot Noir · 黑皮诺 × Cinsault · 神索。'],
 ['Scheurebe · 施埃博','人工种内杂交的另一个例子。']
 ])+p('传统选育至少等两年才能观察开花、结果及果实表现；遗传标记可辅助早期筛选。新品种推广还受消费者接受度限制。')+
 callout('Crossing 与 hybrid','按 species 区分，不按颜色、国家或产区；嫁接不涉及授粉受精。'))+
 section('熟悉红葡萄的中英文与别名',
 table(['原文名称','中文识别'],[
 ['Cabernet Sauvignon','赤霞珠'],['Merlot','梅洛'],['Syrah / Shiraz','西拉／西拉子'],['Grenache / Garnacha','歌海娜'],['Pinot Noir','黑皮诺'],['Gamay','佳美'],['Sangiovese','桑娇维塞'],['Nebbiolo','内比奥罗'],['Barbera','巴贝拉'],['Corvina','科维纳'],['Montepulciano','蒙特普尔恰诺'],['Tempranillo','丹魄'],['Malbec','马尔贝克'],['Carménère','佳美娜'],['Pinotage','皮诺塔吉']
 ])+p('同一品种可有地区别名和不同中文译名。'))+
 section('熟悉白葡萄的中英文与别名',
 table(['原文名称','中文识别'],[
 ['Chardonnay','霞多丽'],['Sauvignon Blanc','长相思'],['Sémillon','赛美蓉'],['Riesling','雷司令'],['Pinot Gris / Pinot Grigio','灰皮诺'],['Gewurztraminer','琼瑶浆'],['Viognier','维欧尼'],['Albariño','阿尔巴利诺'],['Muscat / Moscato','麝香葡萄'],['Glera','格雷拉'],['Verdicchio','维迪奇奥'],['Garganega','卡尔卡耐卡'],['Cortese','柯蒂斯'],['Fiano','菲亚诺']
 ]))+
 section('四种红葡萄的风格对照',
 table(['品种','颜色深度／单宁／酸度','常见香气'],[
 ['Pinot Noir · 黑皮诺','淡／低—中／高','草莓、覆盆子、红樱桃'],
 ['Cabernet Sauvignon · 赤霞珠','深／高／高','黑醋栗、黑樱桃、青椒'],
 ['Merlot · 梅洛','中—深／中／中','草莓、红李子、红樱桃'],
 ['Syrah / Shiraz · 西拉','深／中—高／中','黑莓、黑樱桃、黑胡椒']
 ])+p('典型特征会随气候、成熟程度和酿造改变，品鉴以实际样品为准。<a href="#workbook/1">填写品种练习 →</a>'))
 );

 set('cycle',
 section('葡萄藤的四部分结构',
 p('葡萄品种虽多，基本结构相似；部位和木龄决定结果位置及冬剪对来年收成的影响。')+
 table(['部分','英文与结构','作用及识别'],[
 ['绿色部分','Green parts：当年新梢 Shoot 上有芽 Buds、叶 Leaves、卷须 Tendrils、花与果实 Flowers and berries。','每年新长出的组织，承担光合作用、攀附、开花和结果。'],
 ['一年生木','One-year-old wood / Cane：上一季绿色新梢木质化后的枝条。','到次年春季称一年生木，保留的芽萌发出新一年的新梢，是结果潜力的基础。'],
 ['多年生木','Permanent wood：超过一年的主干 Trunk 及干臂 Cordon（若有）。','形成长期保留的支撑结构，连接地上部分与根系；不同整枝方式下结构和数量不同。'],
 ['根系','Roots：位于土壤中的部分。','吸收水与养分，固定葡萄藤，储存越冬所需的碳水化合物。']
 ]))+
 section('叶、卷须、花与芽',
 p('叶片以光能、水和二氧化碳制造葡萄糖、释放氧气。糖用于生长、成熟和储存，不从土壤直接吸收。葡萄藤不能独立直立，新梢靠卷须攀附铁丝等支撑物。',
 '花聚成花序，兼有雄性和雌性部分；一朵受精花可发育成一颗浆果，一束花序可成为果串。甜果实吸引动物传播种子。',
 '芽位于叶片与新梢相接处。未立即萌发的芽，可在当年形成下一年新梢、叶片、花与卷须的微小结构，并非到冬季才开始形成。')+
 courseFigure('botany','沿新梢辨认叶片、腋芽、卷须及花序；再比较当年绿色部分、一年生枝条与深色永久木质结构。'))+
 section('为什么一年生木关系到下一季结果',
 p('当年新梢逐渐木质化，冬季成为木质枝条，到次年春季成为一年生木。通常只有从前一年形成的芽长出的新梢才能结果，葡萄并不直接长在老主干上；木质化枝条仍有结果管理价值。',
 '每年冬季修剪调整保留的芽数。一年生木可保留为较长的<strong>长枝 Cane：通常 8–20 个芽</strong>，或较短的<strong>短枝 Spur：通常 2–3 个芽</strong>。多年生木的数量和形态也受修剪、整枝控制。')+
 table(['观察情境','先辨认什么'],[
 ['西班牙的短枝修剪葡萄藤','短的一年生枝段与保留多年的木质结构。'],
 ['阿尔萨斯的替换长枝葡萄藤','当年保留、以后会替换的一年生长枝。'],
 ['澳大利亚的水平干臂葡萄藤','水平多年生干臂连接主干，一年生短枝留在其上；不能只因枝条水平就把永久干臂与一年生长枝混为一谈。']
 ])+p('相关操作：<a href="#session2/pruning">冬剪与年周期</a> · <a href="#session2/training">密度与整枝</a>。'))+
 section('葡萄藤的年周期',
 table(['阶段','植株与果实发生什么','风险与管理线索'],[
 ['冬眠 Dormancy','落叶后没有绿色部分，保留木质结构和根系。','严重冬季冻害可能损伤永久结构。'],
 ['萌芽 Budburst 与新梢生长','春季升温使芽展开，形成当年绿色新梢。约 10°C 是开始生长的近似提示，实际时点受品种、环境和年份影响。','嫩芽与新梢容易受到春季霜冻伤害。'],
 ['开花与坐果 Flowering / Fruit set','通常在晚春至初夏，开花后部分花受精形成幼果；果粒继续增大。','天气影响坐果比例及潜在产量。'],
 ['转色 Véraison','转色前果实绿色、坚硬、低糖高酸；转色标志成熟开始，果实变软、颜色或透明感改变。','不是完全成熟或采收的同义词；白葡萄也有转色期。'],
 ['成熟 Ripening','夏末至秋初，果实更柔软、多汁；糖增加、酸下降，颜色、单宁、香气与风味继续发展。','成熟指标不一定同步，须结合品种和目标风格。'],
 ['采收、采后至落叶','依据成熟状况、天气与目标风格决定采收；采后叶片仍可工作并帮助补充储备，之后落叶、回到休眠。','采收结束、落叶与进入休眠不是同一时刻。']
 ])+courseFigure('cycle','按冬眠、萌芽、开花坐果、转色成熟、采收、落叶的顺序阅读；糖、酸、颜色和风味在成熟过程中继续变化。'))+
 section('生长阶段与天气风险',
 p('南北半球季节相反，转色可在北半球约 8 月、南半球约 2 月，但随产区、品种而变。白葡萄由绿色趋向黄绿或金黄，转色并非都变红。',
 '歌海娜与黑皮诺的生长期可不同；早／晚萌芽与早／晚成熟是独立特性。',
 '休眠期与萌芽后霜冻伤及的组织不同，对产量、成熟、品质及成本的后果也不同。')+
 flow('萌芽后遭遇霜冻','嫩芽与新梢受损','当年潜在产量下降')+
 p('<a href="#session2/pruning">月份与年度管理 →</a>'))
 );

 set('needs',
 section('五个生长条件与光合作用',
 p('热量支持生长，阳光为光合作用供能，水与二氧化碳是原料，养分维持植株功能。叶片制糖供生长、成熟和储备，并释放氧气。二氧化碳通常充足，园地差异主要需关注温度、光照、水分与养分。')+
 table(['条件','来源','不要混淆'],[
 ['阳光 Sunlight','太阳直接日照，水面及浅色土壤等反射的光。','光合作用需要光能，不等于气温越高就越有光。'],
 ['热量 Heat','太阳加热及地表吸热后的再辐射。','每个生长阶段均需要适合的温度，不能用光照替代热量作答。'],
 ['水 Water','降雨、灌溉、土壤储水；从根区吸收并送往叶片。','土壤有水还要能供根利用。'],
 ['养分 Nutrients','土壤矿物颗粒、腐殖质、肥料。','养分支持功能，不是土壤直接向果实输送糖。'],
 ['二氧化碳 CO₂','大气。','与水共同参与光合作用。']
 ])+flow('叶片接收光能','水与 CO₂ 转化为糖并释放氧气','支持生长、成熟与储存')+
 p('约 10°C 提示开始生长；萌芽、开花、坐果及成熟均需足够热量。16—22°C 是生长季平均温度的概括范围，并非所有品种和阶段的生存上下限。凉爽地区能使雷司令成熟，却未必适合歌海娜。'))+
 section('光照强度与日照时间',
 p('大多数酿酒葡萄园在南北纬 30°—50°，与热量及休眠需求有关；海拔等调节因素也使区间外存在适种地点。赤道附近太阳能较集中；高纬度斜射使同量能量分散、强度减弱，但夏季白昼较长，额外日照有助德国雷司令成熟。')+
 courseFigure('latitude','比较同量太阳能在低纬度和高纬度地表覆盖的面积，区分阳光强度与夏季日照时间。')+
 table(['因素','作用及条件'],[
 ['朝向 Aspect','朝赤道的坡面通常获光、获热更多：北半球偏南、南半球偏北；坡度、遮挡和具体位置也重要。'],
 ['反射 Reflection','河湖水面、浅色土壤可补充日照；位于水面上方、位置合适的园地较可能获益。'],
 ['云层与海洋影响','临海、近湖常较多云，内陆往往更晴朗；开花坐果时多云会减产，成熟期厚云会限制光合作用和糖积累。']
 ])+p('光照不足妨碍生长与成熟，强烈直射又可能晒伤果皮、带来苦味。少光园地需改善受光，强光处需适度遮阴。'))+
 section('冬季冻害与春季霜冻',
 table(['风险','后果','条件与应对'],[
 ['冬季冻害 Winter freeze','极端低温损伤木质部分，严重时整株死亡；还可能需要拔除、购苗、重植，并等待产量恢复。','低于约 −20°C 是严重风险提示，嫁接部位尤其脆弱；可培土或埋土保护。中国部分产区的埋土防寒说明，保护本身也增加人工与投入。'],
 ['春季霜冻 Frost','近地面空气低于 0°C、组织结冰，损伤萌芽后的嫩芽和新梢，使当年潜在产量下降。','嫩芽约 −2 至 −3°C 受损可作近似例子；耐寒程度随品种、组织、生长阶段、低温持续时间和现场条件改变，不是所有葡萄藤的统一阈值。']
 ])+p('冬季过暖可使休眠不足，甚至一年两季生长结果，影响寿命、品质，并使更多害虫越冬。')+
 table(['春霜保护方法','怎样起作用、有什么前提'],[
 ['加热器 Heaters','园内分布并在霜冻预警时运行，增加热量、促进空气流动；Napa County 有此类实例。'],
 ['风机 Wind machines','混合较暖的上层空气与近地冷空气，有些装置配合加热；缺乏暖空气层时不能期待同样效果。'],
 ['洒水器 Sprinklers','水持续结冰时释放潜热，帮助保护组织；需要正确时机、流量及连续合适供水，不是随意洒一点水，也不是“冰无论多冷都保持 0°C”。'],
 ['园地与树形设计','冷空气下沉，封闭洼地易积冷；选择坡中部并保持排冷路线畅通，较高结构也可让嫩芽远离最冷近地层。']
 ]))+
 section('寒春、酷热与野火',
 p('寒春会推迟萌芽、缩短成熟窗口；开花坐果期间低温也会降低产量。长期极端高温即使供水充足，也可能使活动放缓或停止，光合作用和成熟受阻，严重时致死；高温叠加缺水还可能造成晒伤、脱水与成熟失衡。',
 '酷热干燥增加野火风险，加利福尼亚、智利、澳大利亚均曾受影响。火可毁坏葡萄园和建筑，烟雾影响更广；成熟果实受烟可形成<strong>烟熏污染 Smoke taint</strong>，带来难以完全去除的烟雾或塑料样异味，不同于正常酿造、陈年的烟熏香气。'))+
 section('水分：适度限制与严重胁迫',
 p('根吸收的水送到叶片，叶片经蒸腾散失水分。气温升高，补水需求通常增加。早期需要足够水分长成叶幕；叶片已经充足后，特别是转色后适度限制水分，可抑制新梢过旺、减少遮阴并帮助成熟，前提是仍有足够水维持光合作用。',
 '短暂缺水时植株可减少蒸腾；长期严重干旱会使光合作用停止、叶片萎蔫、果实不能成熟，最终损伤甚至杀死葡萄藤。水过多又会推动枝叶生长，争用糖、增加遮阴；根区积水缺氧，极端时根会死亡。坡地及排水管可排除多余水。',
 '降雨量与时点难控，少雨配合灌溉可提高供水可控性，但受水源、成本、需求与法规限制，仍有干旱风险。新疆较干燥、山东更多雨，可用于比较供水及年份波动，不能据此给酒庄品质排名。')+
 table(['灌溉方式','特点与适用限制'],[
 ['滴灌 Drip irrigation','每株附近滴头向根区精确供水，可配合电脑控制；新西兰葡萄园有系统实例。'],
 ['喷灌 Sprinkler irrigation','喷头供水，耗水较多，湿润环境可能增加病害；专门合理设计、正确运行的系统还可用于防霜。'],
 ['漫灌 Flood irrigation','水在地表铺展下渗，成本较低；需要平坦或非常缓的坡地，以及大量、接近的水源。']
 ]))+
 section('降雨时点与冰雹风险',
 table(['时期或事件','对数量、成熟与健康的影响'],[
 ['开花与坐果期暴雨','干扰开花、受精及坐果，降低潜在产量。'],
 ['生长季持续潮湿','增加真菌病害风险；水分过多又推动枝叶生长和遮阴。'],
 ['临收获暴雨','果粒吸水膨大，风味稀释；严重时裂果并发生继发腐烂。'],
 ['冰雹 Hail','伤叶、伤果、伤藤，严重时毁掉当年收成；Mendoza 是高风险实例。防雹网成本高，但当地可能值得投入。园地分散可分散局部冰雹风险，不能保证完全无损。']
 ])+courseFigure('environment','从防霜、滴灌、防雹与园地排冷认识风险管理。防雹网和防鸟网的对象不同，须按风险选用设施。')+
 p('春季风险主要影响嫩芽、开花坐果和潜在产量；夏秋雨、冰雹及风更易直接伤果。严重叶损、坐果不齐也影响后续成熟，春季风险同样可能降低品质。'))
 );

 set('climate',
 section('气候、天气与年份差异',
 p('<strong>气候 Climate</strong> 描述多年温度、日照和降雨的平均模式；<strong>天气 Weather</strong> 是具体时段实际发生的状况。开花期异常低温、采收前暴雨等会使某一年偏离常态，形成<strong>年份差异 Vintage variation</strong>。',
 '波尔多 2013 年寒冷潮湿、2015 年大部分时间温暖干燥；加利福尼亚 Central Valley 的炎热干燥天气较稳定。单个年份不能代表地区气候。',
 '气候也会在数十年间变化。面对升温、干旱、洪水等变化与极端事件，种植和酿酒均需适应及减缓行动。'))+
 section('生长季平均温度的四档分类',
 p('按生长季平均温度分类：北半球 <strong>4—10 月</strong>，南半球 <strong>10 月至次年 4 月</strong>；不是全年均温或单日最高温。')+
 table(['类别','生长季平均温度'],[
 ['凉爽 Cool','16.5°C 或更低'],['温和 Moderate','16.5—18.5°C'],['温暖 Warm','18.5—21°C'],['炎热 Hot','高于 21°C']
 ])+p('相邻区间以共同端点简写。比较园地还须看大陆度、昼夜温差、降雨总量与分布、阳光强度及日长。'))+
 section('大陆度与昼夜温差',
 table(['概念','比较什么','水体与云层怎样影响'],[
 ['大陆度 Continentality','最热月与最冷月的温差；关系到生长季长短、总热量及适用品种。','海洋、湖泊升温降温比陆地慢，夏季降温、冬季缓和寒冷，通常降低大陆度；内陆更易出现季节极端。'],
 ['昼夜温差 Diurnal range','同一天白天与夜间的温差。凉夜有助保留酸与香气，暖夜使成熟中的变化更快。','大水体甚至河流可夜间保温、白天带来凉风，缩小温差。云层白天遮阳、夜间减少散热；晴朗无云夜晚降温更快。']
 ])+p('大陆性不等于炎热。新疆、内蒙古不同地点可兼有大陆性与不同热量水平，同一省区的园地小气候也不尽相同。'))+
 section('大陆性、海洋性与地中海气候',
 table(['气候类型','典型模式','与生长、风格及风险的联系'],[
 ['大陆性 Continental','季节温差较大，常有较短夏季，入秋降温快；夏季常干。','Chablis · 夏布利、Champagne · 香槟属于凉爽大陆性例子，有春霜、冬季冻害及成熟不足风险，适宜较晚萌芽、较早成熟的品种；温度较高且供水不足时可能需灌溉。'],
 ['海洋性 Maritime','大陆度低，通常凉爽或温和；雨量全年较均匀，温和秋季可延长成熟。','波尔多及法国西部可帮助理解大西洋影响。春夏降雨干扰开花坐果、增加病害，采收季降雨危及果实健康并影响采收安排。'],
 ['地中海 Mediterranean','大陆度较低，夏季温暖干燥，降雨较集中在冬季。','包括地中海沿岸、法国南部、加州大部分沿海，以及智利、南非、澳大利亚的适用地区。夏季少雨利于健康，也有干旱、晒伤与酷热风险；相较海洋性，常见较饱满酒体、成熟单宁、较高酒精及较低酸，仍取决于品种与地点。']
 ])+p('法国西部的大西洋影响向内陆减弱，热量还受南北位置与地形影响。中国部分地区的季风气候夏季多雨，地中海气候则冬季多雨；近海不代表气候类型相同。',
 '巴罗萨的温暖／炎热、干燥条件有利于理解灌木形与供水管理，却不足以推断大陆度。新疆、山东的干湿差异影响年份波动及供水控制，不决定酒的品质高低。'))+
 section('海拔、洋流与雾',
 table(['调节因素','机制','地区例子'],[
 ['海拔 Altitude','通常海拔越高气温越低，可使较低纬度地区仍适合栽培；实际温度还受坡向、位置、风与年份影响。','阿根廷北部 Cafayate，以及香格里拉的高海拔葡萄园。'],
 ['寒流 Cold currents','把冷海水输送到沿岸，海风与雾可将凉意带入内陆。','Humboldt · 洪堡／洪德寒流影响智利；Benguela · 本格拉寒流影响南非。'],
 ['暖流 Warm currents','输送较暖海水，给邻近地区增温影响。','Gulf Stream · 墨西哥湾流影响欧洲西北部。'],
 ['雾 Fog','让过热葡萄园降温，也会减少光照，须结合地点和时段判断。','加利福尼亚、智利 Casablanca Valley。']
 ])+p('朝向 Aspect 指坡面方向。朝赤道的坡面通常获热更多：北半球偏南、南半球偏北。高纬度凉爽地区尤其受益，如 Mosel · 摩泽尔的有利陡坡。<a href="#lesson/soil">园地与土壤 →</a>'))+
 section('糖、酸与风味的成熟不同步',
 table(['成熟指标','通常变化','对目标风格的意义'],[
 ['糖分','成熟中通常增加。','若发酵至干，较高糖通常带来较高潜在酒精度。'],
 ['酸度','成熟中通常下降，炎热时保留酸可能更困难。','关系到清新感与平衡。'],
 ['颜色、单宁、香气与风味','酚类成熟、风味发展和糖酸变化未必同步。','只看甜不甜，可能忽略单宁或风味尚未达到目标。']
 ])+p('品种与环境不匹配时，糖高而风味等指标可能仍不足。黑皮诺、歌海娜的热量需求不同，适宜品种有助平衡成熟；采收仍需结合天气和目标风格。')+
 flow('环境与品种的组合','成熟速度及糖、酸、酚类、风味变化','潜在酒精、平衡与酒的风格')+
 callout('风格不能代替品质判断','凉爽和温暖地区都能生产优质葡萄酒，不能直接按温度排序；气候与天气仍会通过成熟程度、果实健康和成分平衡影响品质潜力。',true))
 );

 set('soil',
 section('园地的局地气候',
 p('葡萄园尺度的中气候／局地气候 <strong>Meso-climate</strong> 受地形及周边环境影响。Local、microclimate 等日常用语涉及的尺度未必相同；应根据当地资源与风险判断地形、土壤的调节作用。')+
 table(['地点或因素','作用及判断条件'],[
 ['海拔、朝向与坡度','通常随海拔升高更凉；朝赤道的坡面通常获光更多，北半球偏南、南半球偏北。坡度、遮挡、风和位置会改变效果。香格里拉高海拔葡萄园利用降温，Mosel 有利陡坡利用受光。'],
 ['坡中部、坡脚与洼地','冷空气下沉，封闭低洼处易积冷，开放坡面可排冷；坡顶、坡面、坡脚的土层和水分也可能不同，应据此选择品种与管理。'],
 ['水体、海风与雾','缓和附近温度变化，但须看水体大小、园地位置、风向和地形；蓬莱海风、焉耆盆地附近博斯腾湖、波尔多的河流都是理解线索。'],
 ['葡萄园围墙','勃艮第围墙可蓄热、挡风，改变局地条件。'],
 ['邻近大树','可能挡风，也会遮光，并与葡萄藤竞争水和养分，保护与遮阴须平衡。']
 ])+p('葡萄牙的陡坡梯田影响种植与受光；苏玳 Sauternes 的秋雾在适宜时点有利于贵腐，供酿甜酒。'))+
 section('土壤颗粒、腐殖质与土层',
 p('土壤位于岩床上，厚数厘米至数米。矿物颗粒来自基岩风化或沉积物；粒径、比例、土层及结构影响根区水分和空气。')+
 table(['组成','英文','与生长条件的关系'],[
 ['石块','Stones','颗粒较大，并非每个园地都有。地表石块参与储热，土壤粗颗粒与结构影响排水。'],
 ['砂／沙','Sand','比黏土颗粒大，通常排水较快，但保水较弱。'],
 ['黏土','Clay','细颗粒可与水结合、提高保水；过多且结构不佳时可能排水不良。'],
 ['腐殖质','Humus','来自动植物残体分解的有机部分，能提供养分并保持水分。']
 ]))+
 section('土壤的储热与升温',
 p('深色表土、石块和岩石吸热后再辐射，可在凉爽地区帮助成熟，如德国葡萄园的石块、勃艮第围墙；并非石头越多越好。',
 '湿土升温需更多能量，可能推迟萌芽。西班牙 Priorat 的多石地表影响热量，陡坡梯田影响地形、作业与受光。'))+
 section('土壤的排水与保水',
 p('黏土、腐殖质能结合水分。黏土过多可能排水不良；砂石排水好而保水弱，过多时即使多雨也可能需灌溉。砂与黏土适当混合的壤土兼顾排水、保水，但适用性仍取决于温度和雨量。',
 '干燥巴罗萨受益于黏土保水，波尔多左岸则重视排水。潮湿处根区积水会缺氧；干旱处若排水过快、储水不足且补水无保障，水分胁迫会限制成熟。',
 '早期水分需足以形成叶幕；叶片充足、尤其转色后，适度限水可抑制旺长、帮助成熟，但不能持续严重缺水。根可深入取水和养分，实际供给受根区及土层限制。')+
 flow('判断降雨、气温与补水','评估土层、保水与排水','选择适宜土壤和管理')+
 p('<a href="#lesson/needs">蒸腾、灌溉与积水风险 →</a>'))+
 section('养分供应与黄化',
 p('根系吸收氮、磷、钾等关键养分。养分过多会使枝叶旺盛、遮阴、妨碍成熟并增加管理投入；耗用后则可用天然或化学肥料补充。',
 '养分不足损害植株和叶片功能。<strong>黄化 Chlorosis</strong> 降低光合作用，影响成熟、品质及产量，如法国 Mâconnais 的黄化葡萄藤。需查明原因再施肥或调整管理。',
 '总养分含量不等于可利用量，石灰质土壤也可能黄化；黄叶未必同因，施肥更多未必更好。')+
 courseFigure('environment','对比健康绿叶与黄化叶片，并把地表、根区水分和环境防护放回同一葡萄园中观察。'))+
 section('土壤、风土与酒的表现',
 p('<strong>Terroir · 风土</strong> 关联品种、环境与地点差异，不能仅用土壤名称概括。栽培需兼顾园地环境、葡萄藤及年度管理；好葡萄是酿好酒的重要前提。',
 '土壤通过水分、热量、养分及对长势和果实成熟的影响参与形成酒的风格与品质，不能推导出石灰岩直接把“石灰味”传进酒里。不同土壤和气候都可能生产好酒，适宜程度要结合品种与管理判断。')+
 callout('从环境到酒的因果链','生长条件 → 植株与果实变化 → 风格、品质与成本。<a href="#session2">葡萄园管理 →</a>',true))
 );
}
